    "type": "SINGLE",
    "difficulty": 5,
    "stem": "A 59-year-old man is evaluated in the emergency receiving room of King Abdulaziz Medical City Jeddah with clinical findings indicative of Hypertensive Emergency with Acute Left Ventricular Failure in ED. Clinical examination and investigative review confirm intravenous nitroglycerin infusion, IV loop diuretic, and non-invasive CPAP support. Vitals reveal blood pressure of 139/73 mm Hg, heart rate of 85/min, respiratory rate of 15/min, and temperature of 37.7C (98.2F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of hypertensive emergency with acute left ventricular failure in ed. Which of the following is the most appropriate next step in clinical management according to Saudi Commission for Health Specialties (SCFHS) guidelines?",
    "options": [
      {
        "text": "Empiric vancomycin monotherapy without Gram-negative and anaerobic coverage",
        "correct": false,
        "explanation": "Incorrect: Restricted glycopeptide monotherapy fails to treat polymicrobial, Gram-negative, or intra-abdominal infectious processes."
      },
      {
        "text": "High-flow oxygen therapy via non-rebreather mask in acute hypercapnic respiratory failure",
        "correct": false,
        "explanation": "Incorrect: Uncontrolled high FiO2 in hypercapnic chronic lung disease abolishes hypoxic respiratory drive, precipitating carbon dioxide narcosis."
      },
      {
        "text": "Empiric aminoglycoside monotherapy for atypical community-acquired respiratory infection",
        "correct": false,
        "explanation": "Incorrect: Aminoglycosides lack reliable tissue penetration and intracellular activity against atypical respiratory organisms such as Mycoplasma."
      },
      {
        "text": "Reassurance and discharge with routine outpatient review in six months",
        "correct": false,
        "explanation": "Incorrect: Delaying intervention in an acutely decompensated or high-risk condition risks rapid irreversible clinical deterioration and preventable complications."
      },
      {
        "text": "Intravenous nitroglycerin infusion, IV loop diuretic, and non-invasive CPAP support",
        "correct": true,
        "explanation": "Correct: According to established evidence-based consensus and clinical practice guidelines, the primary indicated management for this clinical scenario is intravenous nitroglycerin infusion, IV loop diuretic, and non-invasive CPAP support. This directly addresses the underlying pathophysiological abnormality, optimizes therapeutic outcomes, and mitigates disease-specific morbidity."
      }
    ],
    "explanation": "Educational Objective: Understand the diagnosis, guideline-directed management, and clinical rationale for Hypertensive Emergency with Acute Left Ventricular Failure in ED.\\n\\nClinical Discussion: This clinical presentation corresponds to Hypertensive Emergency with Acute Left Ventricular Failure in ED. The cornerstone of management involves intravenous nitroglycerin infusion, IV loop diuretic, and non-invasive CPAP support. Clinical decision-making prioritizes rapid diagnosis, stabilization, and adherence to established clinical guidelines. Alternative choices represent suboptimal management strategies, delayed interventions, or therapies lacking efficacy in this specific clinical presentation.",
    "objective": "Understand the guideline-directed management and pathophysiological basis of Hypertensive Emergency with Acute Left Ventricular Failure in ED.",
